376:   /// <summary>
377:   /// Translates a log4net level to a syslog severity.
378:   /// </summary>
379:   /// <param name="level">A log4net level.</param>
380:   /// <returns>A syslog severity.</returns>
381:   protected virtual SyslogSeverity GetSeverity(Level? level)
382:   {
383:     if (_levelMapping.Lookup(level) is LevelSeverity levelSeverity)
384:     {
385:       return levelSeverity.Severity;
386:     }
387: 
388:     //
389:     // Fall back to sensible default values
390:     //
391: 
392:     if (level is null)
393:     {
394:       // Default setting
395:       return SyslogSeverity.Debug;
396:     }
397:     if (level >= Level.Alert)
398:     {
399:       return SyslogSeverity.Alert;
400:     }
401:     else if (level >= Level.Critical)
402:     {
403:       return SyslogSeverity.Critical;
404:     }
405:     else if (level >= Level.Error)
406:     {
407:       return SyslogSeverity.Error;
408:     }
409:     else if (level >= Level.Warn)
410:     {
411:       return SyslogSeverity.Warning;
412:     }
413:     else if (level >= Level.Notice)
414:     {
415:       return SyslogSeverity.Notice;
416:     }
417:     else if (level >= Level.Info)
418:     {
419:       return SyslogSeverity.Informational;
