      LogLog.Debug(_declaringType, $"Initializing NotAvailableText value to [{notAvailableTextAppSettingsKey}].");
      notAvailableText = notAvailableTextAppSettingsKey;
    }
    NotAvailableText = notAvailableText;
    NullText = nullText;
  }

